#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

installer_path = ROOT / "switch_vision_installer/app/installer.py"
text = installer_path.read_text(encoding="utf-8")
text = text.replace('INSTALLER_VERSION = "2.1.23"', 'INSTALLER_VERSION = "2.1.24"', 1)

old_constants = '''OFFICIAL_RELEASE_API_URL = (\n    "https://api.github.com/repos/zemerdon/"\n    "switch-vision-releases/releases/latest"\n)\n'''
new_constants = '''OFFICIAL_RELEASE_API_URL = (\n    "https://api.github.com/repos/zemerdon/"\n    "switch-vision-releases/releases/latest"\n)\nOFFICIAL_RELEASE_LATEST_URL = (\n    "https://github.com/zemerdon/switch-vision-releases/releases/latest"\n)\nOFFICIAL_RELEASE_DOWNLOAD_BASE = (\n    "https://github.com/zemerdon/switch-vision-releases/releases/download"\n)\nOFFICIAL_RELEASE_RAW_BASE = (\n    "https://raw.githubusercontent.com/zemerdon/switch-vision-releases"\n)\n'''
if old_constants not in text:
    raise SystemExit("ERROR: Installer official release constants block not found")
text = text.replace(old_constants, new_constants, 1)

old_latest = '''def request_json(url: str) -> dict[str, Any]:\n    request = urllib.request.Request(url, headers={"Accept": "application/vnd.github+json", "User-Agent": f"Switch-Vision-Installer/{INSTALLER_VERSION}"})\n    with urllib.request.urlopen(request, timeout=30) as response:\n        return json.load(response)\n\n\ndef latest_release() -> dict[str, Any]:\n    options = load_options()\n    release_api_url = validated_release_api_url(options)\n    payload = request_json(release_api_url)\n    if payload.get("prerelease") and not options.get("allow_prerelease"):\n        raise RuntimeError("Latest GitHub release is marked as a prerelease.")\n\n    version = normalise_version(payload.get("tag_name") or payload.get("name"))\n    if not version:\n        raise RuntimeError("Latest GitHub release does not contain a usable version tag.")\n\n    pattern = str(options.get("release_asset_pattern") or "switch-vision-*.zip")\n    matched = [\n        a for a in payload.get("assets", [])\n        if isinstance(a, dict)\n        and fnmatch(str(a.get("name", "")), pattern)\n        and "source" not in str(a.get("name", "")).lower()\n    ]\n    expected_name = f"switch-vision-{version}.zip"\n    exact = [a for a in matched if str(a.get("name") or "") == expected_name]\n    if len(exact) != 1:\n        names = ", ".join(sorted(str(a.get("name") or "") for a in matched)) or "none"\n        raise RuntimeError(\n            f"Release v{version} must contain exactly one installable asset named "\n            f"{expected_name!r}; matched assets: {names}."\n        )\n    asset = exact[0]\n\n    digest_text = str(asset.get("digest") or "").strip()\n    asset_digest = None\n    if digest_text:\n        match = re.fullmatch(r"sha256:([a-fA-F0-9]{64})", digest_text)\n        if not match:\n            raise RuntimeError(\n                f"Release asset {expected_name} published an unsupported digest {digest_text!r}."\n            )\n        asset_digest = match.group(1).lower()\n\n    asset_name_lower = expected_name.lower()\n    checksum_names = {\n        "sha256sums.txt",\n        "sha256sum.txt",\n        "checksums.txt",\n        f"{asset_name_lower}.sha256",\n        f"{asset_name_lower}.sha256sum",\n    }\n    checksum_assets = [\n        a for a in payload.get("assets", [])\n        if isinstance(a, dict)\n        and str(a.get("name", "")).lower() in checksum_names\n    ]\n    checksum_asset = checksum_assets[0] if checksum_assets else None\n    return {\n        "version": version,\n        "name": payload.get("name") or payload.get("tag_name"),\n        "published_at": payload.get("published_at"),\n        "asset_name": asset.get("name"),\n        "asset_url": asset.get("browser_download_url"),\n        "asset_size": asset.get("size"),\n        "asset_digest": asset_digest,\n        "html_url": payload.get("html_url"),\n        "changelog": payload.get("body") or "",\n        "checksum_asset_name": checksum_asset.get("name") if checksum_asset else None,\n        "checksum_asset_url": checksum_asset.get("browser_download_url") if checksum_asset else None,\n    }\n'''
new_latest = '''def request_json(url: str) -> dict[str, Any]:\n    request = urllib.request.Request(url, headers={"Accept": "application/vnd.github+json", "User-Agent": f"Switch-Vision-Installer/{INSTALLER_VERSION}"})\n    with urllib.request.urlopen(request, timeout=30) as response:\n        return json.load(response)\n\n\ndef official_latest_release_version() -> str:\n    """Resolve the latest public Core tag without consuming GitHub REST quota."""\n    request = urllib.request.Request(\n        OFFICIAL_RELEASE_LATEST_URL,\n        method="HEAD",\n        headers={"User-Agent": f"Switch-Vision-Installer/{INSTALLER_VERSION}"},\n    )\n    with urllib.request.urlopen(request, timeout=30) as response:\n        final_url = str(response.geturl() or "")\n    match = re.search(r"/releases/tag/v?(\\d+\\.\\d+\\.\\d+)(?:$|[/?#])", final_url)\n    if not match:\n        raise RuntimeError(\n            "GitHub latest-release redirect did not resolve to a semantic Core tag."\n        )\n    return normalise_version(match.group(1))\n\n\ndef _official_release_notes(version: str) -> str:\n    url = f"{OFFICIAL_RELEASE_RAW_BASE}/{version}/RELEASE_NOTES.md"\n    request = urllib.request.Request(\n        url,\n        headers={"User-Agent": f"Switch-Vision-Installer/{INSTALLER_VERSION}"},\n    )\n    try:\n        with urllib.request.urlopen(request, timeout=20) as response:\n            return response.read().decode("utf-8", errors="replace")\n    except Exception:\n        return ""\n\n\ndef official_latest_release() -> dict[str, Any]:\n    """Build trusted official release metadata from deterministic public paths."""\n    version = official_latest_release_version()\n    expected_name = f"switch-vision-{version}.zip"\n    checksum_name = f"{expected_name}.sha256"\n    download_base = f"{OFFICIAL_RELEASE_DOWNLOAD_BASE}/{version}"\n    return {\n        "version": version,\n        "name": f"Switch Vision Core v{version}",\n        "published_at": None,\n        "asset_name": expected_name,\n        "asset_url": f"{download_base}/{expected_name}",\n        "asset_size": None,\n        "asset_digest": None,\n        "html_url": f"https://github.com/zemerdon/switch-vision-releases/releases/tag/{version}",\n        "changelog": _official_release_notes(version),\n        "checksum_asset_name": checksum_name,\n        "checksum_asset_url": f"{download_base}/{checksum_name}",\n    }\n\n\ndef latest_release() -> dict[str, Any]:\n    options = load_options()\n    release_api_url = validated_release_api_url(options)\n    if release_api_url == OFFICIAL_RELEASE_API_URL:\n        return official_latest_release()\n\n    # Explicitly opted-in custom release APIs retain the structured API path.\n    payload = request_json(release_api_url)\n    if payload.get("prerelease") and not options.get("allow_prerelease"):\n        raise RuntimeError("Latest GitHub release is marked as a prerelease.")\n\n    version = normalise_version(payload.get("tag_name") or payload.get("name"))\n    if not version:\n        raise RuntimeError("Latest GitHub release does not contain a usable version tag.")\n\n    pattern = str(options.get("release_asset_pattern") or "switch-vision-*.zip")\n    matched = [\n        a for a in payload.get("assets", [])\n        if isinstance(a, dict)\n        and fnmatch(str(a.get("name", "")), pattern)\n        and "source" not in str(a.get("name", "")).lower()\n    ]\n    expected_name = f"switch-vision-{version}.zip"\n    exact = [a for a in matched if str(a.get("name") or "") == expected_name]\n    if len(exact) != 1:\n        names = ", ".join(sorted(str(a.get("name") or "") for a in matched)) or "none"\n        raise RuntimeError(\n            f"Release v{version} must contain exactly one installable asset named "\n            f"{expected_name!r}; matched assets: {names}."\n        )\n    asset = exact[0]\n\n    digest_text = str(asset.get("digest") or "").strip()\n    asset_digest = None\n    if digest_text:\n        match = re.fullmatch(r"sha256:([a-fA-F0-9]{64})", digest_text)\n        if not match:\n            raise RuntimeError(\n                f"Release asset {expected_name} published an unsupported digest {digest_text!r}."\n            )\n        asset_digest = match.group(1).lower()\n\n    asset_name_lower = expected_name.lower()\n    checksum_names = {\n        "sha256sums.txt",\n        "sha256sum.txt",\n        "checksums.txt",\n        f"{asset_name_lower}.sha256",\n        f"{asset_name_lower}.sha256sum",\n    }\n    checksum_assets = [\n        a for a in payload.get("assets", [])\n        if isinstance(a, dict)\n        and str(a.get("name", "")).lower() in checksum_names\n    ]\n    checksum_asset = checksum_assets[0] if checksum_assets else None\n    return {\n        "version": version,\n        "name": payload.get("name") or payload.get("tag_name"),\n        "published_at": payload.get("published_at"),\n        "asset_name": asset.get("name"),\n        "asset_url": asset.get("browser_download_url"),\n        "asset_size": asset.get("size"),\n        "asset_digest": asset_digest,\n        "html_url": payload.get("html_url"),\n        "changelog": payload.get("body") or "",\n        "checksum_asset_name": checksum_asset.get("name") if checksum_asset else None,\n        "checksum_asset_url": checksum_asset.get("browser_download_url") if checksum_asset else None,\n    }\n'''
if old_latest not in text:
    raise SystemExit("ERROR: Installer latest_release block not found")
text = text.replace(old_latest, new_latest, 1)
installer_path.write_text(text, encoding="utf-8", newline="\n")

manager_path = ROOT / "switch_vision_installer/app/component_manager.py"
manager = manager_path.read_text(encoding="utf-8")
manager = manager.replace('''                if spec.kind == "core":\n                    _github_request(\n                        f"https://api.github.com/repos/zemerdon/{repository}/releases/latest"\n                    )\n''', '''                if spec.kind == "core":\n                    installer_core.official_latest_release_version()\n''', 1)
manager = manager.replace('''    if spec.kind == "core":\n        payload = _github_request(\n            f"https://api.github.com/repos/zemerdon/{repository}/releases/latest"\n        )\n        return installer_core.normalise_version(payload.get("tag_name") or payload.get("name"))\n''', '''    if spec.kind == "core":\n        return installer_core.official_latest_release_version()\n''', 1)
old_changelog = '''    if spec.kind == "core":\n        payload = _github_request(\n            f"https://api.github.com/repos/zemerdon/{repository}/releases?per_page=100"\n        )\n        if not isinstance(payload, list):\n            raise RuntimeError("Core release history returned an unexpected response.")\n        sections: list[str] = []\n        for release in payload:\n            if not isinstance(release, dict) or release.get("draft"):\n                continue\n            if release.get("prerelease") and not installer_core.load_options().get("allow_prerelease"):\n                continue\n            version = installer_core.normalise_version(\n                release.get("tag_name") or release.get("name")\n            )\n            if not version:\n                continue\n            body = str(release.get("body") or "").strip()\n            sections.append(f"## v{version}\\n\\n{body or 'No release notes published.'}")\n        text = "\\n\\n".join(sections)\n'''
new_changelog = '''    if spec.kind == "core":\n        # The repository CHANGELOG is authoritative and avoids unauthenticated\n        # GitHub REST release-history quota for a normal UI action.\n        text = _raw_text(repository, "CHANGELOG.md")\n'''
if old_changelog not in manager:
    raise SystemExit("ERROR: Component Manager Core changelog API block not found")
manager = manager.replace(old_changelog, new_changelog, 1)
manager_path.write_text(manager, encoding="utf-8", newline="\n")

config_path = ROOT / "switch_vision_installer/config.yaml"
config = config_path.read_text(encoding="utf-8")
if 'version: "2.1.23"' not in config:
    raise SystemExit("ERROR: Installer config version 2.1.23 not found")
config_path.write_text(config.replace('version: "2.1.23"', 'version: "2.1.24"', 1), encoding="utf-8", newline="\n")

changelog_path = ROOT / "switch_vision_installer/CHANGELOG.md"
changelog = changelog_path.read_text(encoding="utf-8")
entry = '''## v2.1.24 — GitHub rate-limit-safe Core release discovery\n\n- Stop using unauthenticated `api.github.com` requests for normal official Core version/status/install discovery.\n- Resolve the latest public Core version through GitHub's standard `/releases/latest` redirect and deterministic release asset names.\n- Continue requiring the exact `switch-vision-<version>.zip` asset and its published `.sha256` checksum before installation.\n- Read the Core changelog from the public repository instead of the GitHub releases REST API.\n- Preserve explicit custom release API support behind `allow_custom_release_source`; only opted-in custom sources use the structured API path.\n- Prevent exhausted unauthenticated GitHub REST quotas from blocking normal Switch Vision update checks.\n\n'''
if not changelog.startswith("# Changelog\n\n"):
    raise SystemExit("ERROR: unexpected Installer changelog header")
changelog = "# Changelog\n\n" + entry + changelog[len("# Changelog\n\n"):]
changelog_path.write_text(changelog, encoding="utf-8", newline="\n")

regression = ROOT / "tests/test_v2_1_24_rate_limit_safe_release.py"
regression.write_text('''from __future__ import annotations\n\nimport sys\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nROOT = Path(__file__).resolve().parents[1]\nAPP = ROOT / "switch_vision_installer" / "app"\nif str(APP) not in sys.path:\n    sys.path.insert(0, str(APP))\n\nimport installer\nimport component_manager\n\n\nclass FakeRedirectResponse:\n    def __enter__(self):\n        return self\n\n    def __exit__(self, exc_type, exc, tb):\n        return False\n\n    def geturl(self):\n        return "https://github.com/zemerdon/switch-vision-releases/releases/tag/2.4.3"\n\n\nclass InstallerRateLimitSafeReleaseTests(unittest.TestCase):\n    def test_official_version_uses_releases_redirect_not_rest_api(self):\n        seen = []\n\n        def fake_urlopen(request, timeout=0):\n            seen.append((request.full_url, request.get_method()))\n            return FakeRedirectResponse()\n\n        with patch.object(installer.urllib.request, "urlopen", side_effect=fake_urlopen):\n            self.assertEqual(installer.official_latest_release_version(), "2.4.3")\n\n        self.assertEqual(seen, [(installer.OFFICIAL_RELEASE_LATEST_URL, "HEAD")])\n        self.assertFalse(any("api.github.com" in url for url, _ in seen))\n\n    def test_official_metadata_is_deterministic_and_checksum_backed(self):\n        with patch.object(installer, "official_latest_release_version", return_value="2.4.3"), \\\n             patch.object(installer, "_official_release_notes", return_value="notes"):\n            release = installer.official_latest_release()\n\n        self.assertEqual(release["asset_name"], "switch-vision-2.4.3.zip")\n        self.assertEqual(\n            release["asset_url"],\n            "https://github.com/zemerdon/switch-vision-releases/releases/download/2.4.3/switch-vision-2.4.3.zip",\n        )\n        self.assertEqual(release["checksum_asset_name"], "switch-vision-2.4.3.zip.sha256")\n        self.assertTrue(release["checksum_asset_url"].endswith("/switch-vision-2.4.3.zip.sha256"))\n        self.assertIsNone(release["asset_digest"])\n\n    def test_official_latest_release_does_not_call_request_json(self):\n        options = {\n            "release_api_url": installer.OFFICIAL_RELEASE_API_URL,\n            "allow_custom_release_source": False,\n            "release_asset_pattern": "switch-vision-*.zip",\n            "allow_prerelease": False,\n        }\n        with patch.object(installer, "load_options", return_value=options), \\\n             patch.object(installer, "official_latest_release", return_value={"version": "2.4.3"}) as official, \\\n             patch.object(installer, "request_json", side_effect=AssertionError("REST API must not be used")):\n            self.assertEqual(installer.latest_release()["version"], "2.4.3")\n            official.assert_called_once_with()\n\n    def test_component_manager_core_status_uses_same_non_api_resolver(self):\n        component_manager.clear_cache()\n        core = next(spec for spec in component_manager.COMPONENTS if spec.component_id == "core")\n        with patch.object(installer, "official_latest_release_version", return_value="2.4.3") as latest, \\\n             patch.object(component_manager, "_github_request", side_effect=AssertionError("REST API must not be used")):\n            self.assertEqual(component_manager._remote_version(core), "2.4.3")\n            latest.assert_called_once_with()\n\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding="utf-8", newline="\n")

print("Prepared Switch Vision Installer v2.1.24 rate-limit-safe release discovery hotfix")
